 assert.deepEqual(active.versions,[{version_id:PHOTO_CANCELLED.version,percentage:100}],'Exact single recorded photo version at 100% required');
 assert.equal(version.id,PHOTO_CANCELLED.version,'Exact CLI-owned version required');
 for(const [r,id,source,conclusion]of [[run,PHOTO_CANCELLED.run,PHOTO_CANCELLED.source,'cancelled'],[previousRun,PHOTO_CANCELLED.previousRun,PHOTO_CANCELLED.previousSource,'success']]){
  assert.equal(r.id,id);assert.equal(r.head_sha,source);assert.equal(r.head_branch,'main');assert.equal(r.event,'push');assert.equal(r.path,'.github/workflows/cloudflare-production-promote.yml');assert.equal(r.status,'completed');assert.equal(r.conclusion,conclusion);
 }
 assert.equal(job.id,PHOTO_CANCELLED.job);assert.equal(job.run_id,PHOTO_CANCELLED.run);assert.equal(job.name,'promote');assert.equal(job.conclusion,'cancelled');
 assert.deepEqual(job.steps.map(({number,name,conclusion})=>({number,name,conclusion})),PHOTO_CANCELLED_STEPS,'Every original successful, skipped, cancelled and failed gate must remain exactly as recorded');
 assert.equal(previousJob.id,PHOTO_CANCELLED.previousJob);assert.equal(previousJob.run_id,PHOTO_CANCELLED.previousRun);assert.equal(previousJob.name,'promote');assert.equal(previousJob.conclusion,'success');
 for(const[k,v]of Object.entries(requiredOwner))assert.equal(owner[k],v,'Exact original owned-deployment receipt required: '+k);
 assert.equal(previousOwner.source,PHOTO_CANCELLED.previousSource);assert.equal(String(previousOwner.run),String(PHOTO_CANCELLED.previousRun));assert.equal(previousOwner.versionId,PHOTO_CANCELLED.previousVersion);assert.equal(previousOwner.deploymentId,PHOTO_CANCELLED.previousDeployment);
 assert.equal(report.source,PHOTO_CANCELLED.source);assert.equal(String(report.run),String(PHOTO_CANCELLED.run));assert.equal(report.workflowStatus,'cancelled');assert.equal(report.releaseVerified,false);assert.equal(report.deployedVersion,PHOTO_CANCELLED.version,'Cancelled run must remain explicitly unverified');
